sition - c2.Position).Magnitude end return math.huge end local function getClosestPlayerInRange(range) local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") if not hrp then return nil end local closest = nil local closestDist = math.huge for _, p in pairs(PlayersSvc:GetPlayers()) do if p ~= LocalPlayer and p.Character then local dist = getPlayerDistance(LocalPlayer, p) if dist <= range and dist < closestDist then closestDist = dist closest = p end end end return closest end local function spawnWeaponFromServer(weaponName) pcall(function() local ssWeapon = ServerStorage:FindFirstChild(weaponName) if ssWeapon then local clone = ssWeapon:Clone() clone.Parent = LocalPlayer.Backpack or LocalPlayer.Character end end) pcall(function() LocalPlayer:Chat("/sg " .. weaponName) end) end local function giveMopServerSide() pcall(function() GIVE_MOP:FireServer() end) task.wait(1) pcall(function() local mopInSS = ServerStorage and ServerStorage:FindFirstChild("Mop") if mopInSS then local clone = mopInSS:Clone(); clone.Parent = LocalPlayer.Backpack end end) end local function raycastSilentAim() local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") if not hrp then return nil end local closest = nil local closestScore = math.huge local camPos = Camera.CFrame.Position local camDir = Camera.CFrame.LookVector for _, p in pairs(PlayersSvc:GetPlayers()) do if p ~= LocalPlayer and p.Character then local head = p.Character:FindFirstChild("Head") if head then local headPos = head.Position local toTarget = (headPos - camPos).Magnitude local dirToTarget = (headPos - camPos).Unit local dot = camDir:Dot(dirToTarget) if dot > 0.5 then local screenPos, onScreen = Camera:WorldToViewportPoint(headPos) if onScreen then local center = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2) local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude local fovMax = (AimBotFOV / 100) * Camera.ViewportSize.X if screenDist <= fovMax then local velocity = p.Character:FindFirstChild("Humanoid") and p.Character.Humanoid.MoveDirection or Vector3.new(0, 0, 0) local predictedPos = headPos + (velocity * AimPrediction) local predictedScreen, predOnScreen = Camera:WorldToViewportPoint(predictedPos) local predDist = predOnScreen and (Vector2.new(predictedScreen.X, predictedScreen.Y) - center).Magnitude or screenDist local score = predDist + (toTarget * 0.05) if score < closestScore then closestScore = score closest = {Head = head, Position = predictedPos, Player = p} end end end end end end end return closest end local function silentAimLoop() task.spawn(function() while SilentAimActive do local target = raycastSilentAim() if target and target.Head then pcall(function() fireHit(target.Head.Parent:FindFirstChild("Humanoid"), target.Head, SelectedTool) end) end task.wait(0.05) end end) end local function getAimTarget() local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") if not hrp then return nil end local closest = nil local closestScore = math.huge local currentPos = hrp.Position for _, player in pairs(PlayersSvc:GetPlayers()) do if player ~= LocalPlayer and player.Character then local head = player.Character:FindFirstChild("Head") if head then local velocity = player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.MoveDirection or Vector3.new(0, 0, 0) local predictedPos = head.Position + (velocity * AimPrediction) local screenPos, onScreen = Camera:WorldToViewportPoint(predictedPos) if onScreen then local viewportCenter = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2) local distanceFromCenter = (Vector2.new(screenPos.X, screenPos.Y) - viewportCenter).Magnitude local maxFOV = (AimBotFOV / 100) * Camera.ViewportSize.X if distanceFromCenter <= maxFOV then local worldDist = (currentPos - head.Position).Magnitude local score = distanceFromCenter + (worldDist * 0.1) if score < closestScore then closestScore = score closest = {Head = head, PredictedPos = predictedPos} end end end end end end return closest end local function smoothAim(currentCF, targetPos, smoothness) return currentCF:Lerp(CFrame.new(currentCF.Position, targetPos), math.clamp(smoothness, 0.05, 1)) end local function aimBotLoop() task.spawn(function() while AimBotActive do local target = getAimTarget() if target then local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") if hrp then Camera.CFrame = smoothAim(Camera.CFrame, target.PredictedPos, AimSmoothness) pcall(function() fireHit(target.Head.Parent:FindFirstChild("Humanoid"), target.Head, SelectedTool) end) end end if FOVCircle then FOVCircle.Radius = (AimBotFOV / 100) * Camera.ViewportSize.X FOVCircle.Position = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2) FOVCircle.Visible = true end task.wait() end if FOVCircle then FOVCircle:Destroy(); FOVCircle = nil end end) end local function startKillAll() task.spawn(function() while KillAllActive do local targets = {} for _, p in pairs(PlayersSvc:GetPlayers()) do if p ~= LocalPlayer and p.Character then local h = p.Character:FindFirstChild("Humanoid") if h and h.Health > 0 then table.insert(targets, p) end end end for _, p in ipairs(targets) do pcall(function() killPlayer(p, SelectedTool) end) end task.wait(0.05) end unequipTool() end) end local function startKillAura() task.spawn(function() while KillAuraActive do local target = getClosestPlayerInRange(KillAuraRange) if target then killPlayer(target, SelectedTool) end task.wait(0.05) end unequipTool() end) end local function getCleanParts() local cleanPart = Workspace:FindFirstChild("CleanPart") if not cleanPart then return {} end local parts = {} for _, obj in pairs(cleanPart:GetDescendants()) do if obj:IsA("BasePart") and obj:FindFirstChild("ProximityPrompt") then table.insert(parts, obj) end end return parts end local function startMopJob() task.spawn(function() giveMopServerSide() 