 = moveDir + Camera.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then moveDir = moveDir - Vector3.new(0, 1, 0) end if moveDir.Magnitude > 0.1 then FlyBG.CFrame = CFrame.new(hrp.Position, hrp.Position + moveDir.Unit) FlyBV.Velocity = moveDir.Unit * FlySpeed else FlyBV.Velocity = Vector3.new(0, 0, 0) end end) end local function stopFly() FlyActive = false if FlyConnection then FlyConnection:Disconnect(); FlyConnection = nil end if FlyBV then FlyBV:Destroy(); FlyBV = nil end if FlyBG then FlyBG:Destroy(); FlyBG = nil end local character = LocalPlayer.Character if character then pcall(function() for _, part in pairs(character:GetDescendants()) do if part:IsA("BasePart") then part.CanCollide = true end end end) pcall(function() character.Humanoid.PlatformStand = false end) end end local function startNoClip() NoClipActive = true local character = LocalPlayer.Character if not character then return end pcall(function() for _, part in pairs(character:GetDescendants()) do if part:IsA("BasePart") then part.CanCollide = false end end end) local hrp = character:FindFirstChild("HumanoidRootPart") if hrp then NoclipBV = Instance.new("BodyVelocity") NoclipBV.MaxForce = Vector3.new(9e9, 9e9, 9e9) NoclipBV.Velocity = Vector3.new(0, 0, 0) NoclipBV.Parent = hrp NoclipConnection = RunService.Heartbeat:Connect(function() if not NoClipActive then if NoclipBV then NoclipBV:Destroy() end if NoclipConnection then NoclipConnection:Disconnect() end pcall(function() for _, part in pairs(character:GetDescendants()) do if part:IsA("BasePart") then part.CanCollide = true end end end) return end local moveDir = Vector3.new(0, 0, 0) if UIS:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + Camera.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - Camera.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - Camera.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + Camera.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then moveDir = moveDir - Vector3.new(0, 1, 0) end if moveDir.Magnitude > 0.1 then NoclipBV.Velocity = moveDir.Unit * (FlySpeed * 0.8) else NoclipBV.Velocity = Vector3.new(0, 0, 0) end end) end end local function stopNoClip() NoClipActive = false if NoclipConnection then NoclipConnection:Disconnect(); NoclipConnection = nil end if NoclipBV then NoclipBV:Destroy(); NoclipBV = nil end local character = LocalPlayer.Character if character then pcall(function() for _, part in pairs(character:GetDescendants()) do if part:IsA("BasePart") then part.CanCollide = true end end end) end end local function startSpeed() SpeedActive = true local character = LocalPlayer.Character if not character then return end local h = character:FindFirstChild("Humanoid") if h then h.WalkSpeed = 16 * SpeedMultiplier end end local function stopSpeed() SpeedActive = false local character = LocalPlayer.Character if character then local h = character:FindFirstChild("Humanoid") if h then h.WalkSpeed = 16 end end end local function startESP() EspActive = true for _, conn in pairs(ESPConnections) do if conn then if conn.conn then conn.conn:Disconnect() end; if conn.draw then conn.draw:Remove() end end end ESPConnections = {} for _, player in pairs(PlayersSvc:GetPlayers()) do if player ~= LocalPlayer then local function createESP() local character = player.Character if not character then return end local hrp = character:FindFirstChild("HumanoidRootPart") if not hrp then return end local box = Drawing.new("Box") box.Size = Vector2.new(50, 80) box.Color = Color3.fromRGB(0, 255, 136) box.Thickness = 1.5 box.Filled = false box.Transparency = 0.6 box.Visible = true table.insert(ESPConnections, {draw = box, player = player}) local nameLabel = Drawing.new("Text") nameLabel.Text = player.Name nameLabel.Size = 14 nameLabel.Color = Color3.fromRGB(0, 255, 136) nameLabel.Thickness = 1 nameLabel.Center = true nameLabel.Outline = true nameLabel.OutlineColor = Color3.fromRGB(0, 0, 0) nameLabel.Font = 2 nameLabel.Transparency = 0.7 nameLabel.Visible = true table.insert(ESPConnections, {draw = nameLabel, player = player}) local connection = RunService.Heartbeat:Connect(function() if not EspActive then if box then box:Remove() end if nameLabel then nameLabel:Remove() end if connection then connection:Disconnect() end return end local char = player.Character if not char then box.Visible = false; nameLabel.Visible = false; return end local hrp2 = char:FindFirstChild("HumanoidRootPart") if hrp2 then local screenPos, _ = Camera:WorldToViewportPoint(hrp2.Position) box.Position = Vector2.new(screenPos.X - 25, screenPos.Y - 40) box.Visible = true nameLabel.Position = Vector2.new(screenPos.X, screenPos.Y + 45) nameLabel.Visible = true else box.Visible = false nameLabel.Visible = false end end) table.insert(ESPConnections, {conn = connection, player = player}) end task.spawn(createESP) end end end local function stopESP() EspActive = false for _, conn in pairs(ESPConnections) do if conn then if conn.conn then conn.conn:Disconnect() end; if conn.draw then conn.draw:Remove() end end end ESPConnections = {} end local function teleportToPlayer(targetName) if not targetName or targetName == "" then return end for _, p in pairs(PlayersSvc:GetPlayers()) do if p.Name:lower():find(targetName:lower()) and p.Character then local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") local targetHrp = p.Character:FindFirstChild("HumanoidRootPart") if hrp and targetHrp then hrp.CFrame = targetHrp.CFrame print("[HydraSec] Teleported to " .. p.Name) return end end end print("[HydraSec] Player not found: " .. targetName) end local Window = Rayfield:CreateWindow({ name = "HydraSec", subtitle = "by HydraSec", sidebarLayout = true, configuration = { autoSave = true, autoLoad = true, fileName = "HydraSec" }, }) local playerTab = Window:CreateTab({name = "Player"}) local teleportInput = playerTab:CreateInput({name = "Teleport To", value = "", placeholder = "Username"}) playerTab:CreateButton({name = "Teleport", callback = function() teleportToPlayer(teleportInput.Value) end}) playerTab:CreateToggle({name = "Fly", value = false, flag = "Fly", callback = function(Value) FlyActive = Value; if Value then startFly() else stopFly() end end}) playerTab:CreateSlider({name = "Fly Speed", range = {10, 200}, increment = 5, value = 50, flag = "FlySpeed", callback = function(Value) FlySpeed = Value end}) playerTab:CreateToggle({name = "NoClip (Wall Hack)", value = false, flag = "NoClip", callback = function(Value) NoClipActive = Value; if Value then startNoClip() else stopNoClip() end end}) playerTab:CreateToggle({name = "Speed Boost", value = false, flag = "Speed", callback = function(Value) SpeedActive = Value; if Value then startSpeed() else stopSpeed() end end}) playerTab:CreateSlider({name = "Speed Multiplier", range = {1, 10}, increment = 1, value = 3, flag = "SpeedMult", callback = function(Value) SpeedMultiplier = Value; if SpeedActive then startSpeed() end end}) playerTab:CreateToggle({name = "ESP (Through Walls)", value = false, flag = "ESP", callback = function(Value) EspActive = Value; if Value then startESP() else stopESP() end end}) playerTab:CreateButton({name = "Full ESP", callback = function() EspActive = true; startESP() end}) playerTab:CreateButton({name = "Disable ESP", callback = function() stopESP() end}) local killTab = Window:CreateTab({name = "Kill"}) killTab:CreateToggle({name = "Kill All", value = false, flag = "KillAll", callback = function(Value) KillAllActive = Value; if Value then equipTool(SelectedTool); startKillAll() else unequipTool() end end}) killTab:CreateToggle({name = "Kill Aura", value = false, flag = "KillAura", callback = function(Value) KillAuraActive = Value; if Value then equipTool(SelectedTool); st