lActive; if KillAllActive then equipTool(SelectedTool); startKillAll() end end}) local k2 = killTab:CreateKeybind({name = "Kill Aura", value = Enum.KeyCode.F7, hold = false, flag = "KeybindKillAura", callback = function(key) KillAuraActive = not KillAuraActive; if KillAuraActive then equipTool(SelectedTool); startKillAura() end end}) local k3 = killTab:CreateKeybind({name = "Silent Aim", value = Enum.KeyCode.F8, hold = false, flag = "KeybindSilentAim", callback = function(key) SilentAimActive = not SilentAimActive; if SilentAimActive then silentAimLoop() end end}) local k4 = killTab:CreateKeybind({name = "Aim Bot", value = Enum.KeyCode.F9, hold = false, flag = "KeybindAimBot", callback = function(key) AimBotActive = not AimBotActive; if AimBotActive then equipTool(SelectedTool); if not FOVCircle then FOVCircle = Drawing.new("Circle"); FOVCircle.Thickness = 2; FOVCircle.NumSides = 64; FOVCircle.Filled = false; FOVCircle.Transparency = 0.6; FOVCircle.Color = Color3.fromRGB(0, 255, 136) end; aimBotLoop() else if FOVCircle then FOVCircle:Destroy(); FOVCircle = nil end end end}) local k6 = playerTab:CreateKeybind({name = "Toggle Fly", value = Enum.KeyCode.F5, hold = false, flag = "KeybindFly", callback = function(key) FlyActive = not FlyActive; if FlyActive then startFly() else stopFly() end end}) print("[HydraSec] Loaded | Fly F5 | NoClip | ESP | Speed | Teleport | Kill All + Aura + Silent + Aim") print("[HydraSec] Server-side: ServerStorage:{weapon} + /sg chat") print("[HydraSec] Mop Job: GiveMop to CleanPart, Teleport, $20/clean")